// ============================================================================
//  QIV_19_VolumeDelta - VALIDATION HARNESS ONLY. Not an indicator for trading use.
//  Generated by validation/probes/gen_harness.py - do not edit by hand.
//
//  Runs the real compiled QI_19_VolumeDelta as a normal chart indicator (by inheritance, no hosting)
//  and appends its values per bar to a CSV so they can be checked against the reference
//  implementations in validation/pytests and the original indicator's EveryBar export.
//  Educational use only - not financial advice.
// ============================================================================
#region Using declarations
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Cbi;
using NinjaTrader.Gui;
using NinjaTrader.Gui.Chart;
using NinjaTrader.Gui.SuperDom;
using NinjaTrader.Gui.Tools;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.Core.FloatingPoint;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
	public class QIV_19_VolumeDelta : QI_19_VolumeDelta
	{
		private StreamWriter writer;

		protected override void OnStateChange()
		{
			base.OnStateChange();

			if (State == State.SetDefaults)
			{
				Name			= "QIV_19_VolumeDelta";
				Description		= "Validation harness for QI_19_VolumeDelta: writes its values per bar to CSV. Not for trading use.";
				ShowDisclaimer	= false;
				OutputFolder	= @"C:\Users\rajib\OneDrive\Documents\ninjatrader_quant_indicators\validation\runs";
			}
			else if (State == State.DataLoaded)
			{
				try
				{
					Directory.CreateDirectory(OutputFolder);
					string tf   = BarsPeriod.BarsPeriodType + "-" + BarsPeriod.Value;
					string file = Path.Combine(OutputFolder, "qiv_19_VolumeDelta_" + Instrument.MasterInstrument.Name + "_" + tf + ".csv");
					writer = new StreamWriter(file, false);
					writer.WriteLine("BarTime,Bar,Open,High,Low,Close,Volume,QI_19_VolumeDelta.Values[0],QI_19_VolumeDelta.Values[1],QI_19_VolumeDelta.Values[2],QI_19_VolumeDelta.VolDelta,QI_19_VolumeDelta.CumDelta20,QI_19_VolumeDelta.DeltaSMA10");
					writer.AutoFlush = true;
				}
				catch (Exception ex) { Print("QIV_19_VolumeDelta init error: " + ex.Message); writer = null; }
			}
			else if (State == State.Terminated)
			{
				if (writer != null) { try { writer.Close(); } catch {} writer = null; }
			}
		}

		protected override void OnBarUpdate()
		{
			base.OnBarUpdate();

			if (BarsInProgress != 0 || writer == null)
				return;
			try
			{
				var sb = new StringBuilder();
				sb.Append(Time[0].ToString("yyyy-MM-dd HH:mm:ss")).Append(',').Append(CurrentBar)
				  .Append(',').Append(Open[0].ToString("F4")).Append(',').Append(High[0].ToString("F4"))
				  .Append(',').Append(Low[0].ToString("F4")).Append(',').Append(Close[0].ToString("F4"))
				  .Append(',').Append(Volume[0].ToString("F0"));
				sb.Append(',').Append(Safe(Values[0][0]));
				sb.Append(',').Append(Safe(Values[1][0]));
				sb.Append(',').Append(Safe(Values[2][0]));
				sb.Append(',').Append(Safe(VolDelta[0]));
				sb.Append(',').Append(Safe(CumDelta20[0]));
				sb.Append(',').Append(Safe(DeltaSMA10[0]));
				writer.WriteLine(sb.ToString());
			}
			catch (Exception ex) { Print("QIV_19_VolumeDelta row error at bar " + CurrentBar + ": " + ex.Message); }
		}

		private static string Safe(double v)
		{
			return (double.IsNaN(v) || double.IsInfinity(v)) ? "" : v.ToString("F4");
		}

		public override string DisplayName
		{
			get { return "QIV 19_VolumeDelta (validation)"; }
		}

		[NinjaScriptProperty]
		[Display(Name = "Output Folder", Order = 99, GroupName = "Validation")]
		public string OutputFolder { get; set; }
	}
}
